package com.example.rokidgeminisecretary;
import android.app.*;import android.widget.*;import org.json.*;import java.util.function.Consumer;
final class QuietHoursDialog {
 static void show(Activity owner,JSONObject initial,Consumer<JSONObject> submit){LinearLayout box=new LinearLayout(owner);box.setOrientation(1);box.setPadding(20,12,20,12);TextView note=new TextView(owner);note.setText("グラスの端末時刻・毎日の時間帯です。通知・TOPIC・AMBを表示のみへ切り替えます。直接話しかけた会話は対象外。開始＝終了は終日。現在の発話は次の区切りで切り替わります。");box.addView(note);CheckBox enabled=new CheckBox(owner);enabled.setText("静かな時間を有効にする（初期OFF）");enabled.setChecked(initial.optBoolean("enabled"));box.addView(enabled);String[] keys={"start","end","start2","end2"};int[] defaults={1320,420,540,1080};EditText[] fields=new EditText[4];for(int i=0;i<4;i++){EditText input=new EditText(owner);int minute=initial.optInt(keys[i],defaults[i]);input.setText(String.format(java.util.Locale.ROOT,"%02d:%02d",minute/60,minute%60));input.setHint((i<2?"時間帯①":"時間帯②")+(i%2==0?"開始":"終了"));input.setSingleLine(true);box.addView(input);fields[i]=input;}CheckBox second=new CheckBox(owner);second.setText("時間帯②も使う");second.setChecked(initial.optBoolean("second"));box.addView(second);CheckBox[] exceptions=new CheckBox[3];String[] kinds={"error","schedule","codex"},names={"エラー・権限通知","予定通知","Codex通知"};for(int i=0;i<3;i++){CheckBox cb=new CheckBox(owner);cb.setText("例外として読み上げる："+names[i]);cb.setChecked(java.util.Arrays.asList(initial.optString("allow").split(",")).contains(kinds[i]));box.addView(cb);exceptions[i]=cb;}ScrollView scroll=new ScrollView(owner);scroll.addView(box);AlertDialog dialog=new AlertDialog.Builder(owner).setTitle("グラスの静かな時間").setView(scroll).setPositiveButton("設定を送る",null).setNegativeButton("閉じる",null).create();dialog.setOnShowListener(v->dialog.getButton(-1).setOnClickListener(b->{try{JSONObject config=new JSONObject().put("enabled",enabled.isChecked()).put("second",second.isChecked());for(int i=0;i<4;i++)config.put(keys[i],QuietHoursPolicy.minute(fields[i].getText().toString()));java.util.ArrayList<String> allow=new java.util.ArrayList<>();for(int i=0;i<3;i++)if(exceptions[i].isChecked())allow.add(kinds[i]);config.put("allow",String.join(",",allow));submit.accept(QuietHoursPolicy.checked(config).put("baseRevision",initial.optLong("revision")));dialog.dismiss();}catch(Exception e){fields[0].setError(e.getMessage());}}));dialog.show();}
 private QuietHoursDialog(){}
}
